CREATE VIEW [dbo].[contrattokinddefaultview] AS SELECT CASE WHEN contrattokind.active = 'S' THEN 'Si' WHEN contrattokind.active = 'N' THEN 'No' END AS contrattokind_active,CASE WHEN contrattokind.assegnoaggiuntivo = 'S' THEN 'Si' WHEN contrattokind.assegnoaggiuntivo = 'N' THEN 'No' END AS contrattokind_assegnoaggiuntivo, contrattokind.costolordoannuo AS contrattokind_costolordoannuo, contrattokind.costolordoannuooneri AS contrattokind_costolordoannuooneri, contrattokind.ct AS contrattokind_ct, contrattokind.cu AS contrattokind_cu, contrattokind.description AS contrattokind_description,CASE WHEN contrattokind.elementoperequativo = 'S' THEN 'Si' WHEN contrattokind.elementoperequativo = 'N' THEN 'No' END AS contrattokind_elementoperequativo, contrattokind.idcontrattokind,CASE WHEN contrattokind.indennitadiateneo = 'S' THEN 'Si' WHEN contrattokind.indennitadiateneo = 'N' THEN 'No' END AS contrattokind_indennitadiateneo,CASE WHEN contrattokind.indennitadiposizione = 'S' THEN 'Si' WHEN contrattokind.indennitadiposizione = 'N' THEN 'No' END AS contrattokind_indennitadiposizione,CASE WHEN contrattokind.indvacancacontrattuale = 'S' THEN 'Si' WHEN contrattokind.indvacancacontrattuale = 'N' THEN 'No' END AS contrattokind_indvacancacontrattuale, contrattokind.lt AS contrattokind_lt, contrattokind.lu AS contrattokind_lu, contrattokind.oremaxcompitididatempoparziale AS contrattokind_oremaxcompitididatempoparziale, contrattokind.oremaxcompitididatempopieno AS contrattokind_oremaxcompitididatempopieno, contrattokind.oremaxdidatempoparziale AS contrattokind_oremaxdidatempoparziale, contrattokind.oremaxdidatempopieno AS contrattokind_oremaxdidatempopieno, contrattokind.oremaxgg AS contrattokind_oremaxgg, contrattokind.oremaxtempoparziale AS contrattokind_oremaxtempoparziale, contrattokind.oremaxtempopieno AS contrattokind_oremaxtempopieno, contrattokind.oremincompitididatempoparziale AS contrattokind_oremincompitididatempoparziale, contrattokind.oremincompitididatempopieno AS contrattokind_oremincompitididatempopieno, contrattokind.oremindidatempoparziale AS contrattokind_oremindidatempoparziale, contrattokind.oremindidatempopieno AS contrattokind_oremindidatempopieno, contrattokind.oremintempoparziale AS contrattokind_oremintempoparziale, contrattokind.oremintempopieno AS contrattokind_oremintempopieno, contrattokind.orestraordinariemax AS contrattokind_orestraordinariemax,CASE WHEN contrattokind.parttime = 'S' THEN 'Si' WHEN contrattokind.parttime = 'N' THEN 'No' END AS contrattokind_parttime,CASE WHEN contrattokind.scatto = 'S' THEN 'Si' WHEN contrattokind.scatto = 'N' THEN 'No' END AS contrattokind_scatto, contrattokind.sortcode AS contrattokind_sortcode,CASE WHEN contrattokind.tempdef = 'S' THEN 'Si' WHEN contrattokind.tempdef = 'N' THEN 'No' END AS contrattokind_tempdef, contrattokind.title,CASE WHEN contrattokind.totaletredicesima = 'S' THEN 'Si' WHEN contrattokind.totaletredicesima = 'N' THEN 'No' END AS contrattokind_totaletredicesima,CASE WHEN contrattokind.tredicesimaindennitaintegrativaspeciale = 'S' THEN 'Si' WHEN contrattokind.tredicesimaindennitaintegrativaspeciale = 'N' THEN 'No' END AS contrattokind_tredicesimaindennitaintegrativaspeciale, isnull('Tipologia: ' + contrattokind.title + '; ','') as dropdown_title FROM [dbo].contrattokind WITH (NOLOCK)  WHERE  contrattokind.idcontrattokind IS NOT NULL 

GO

-- CREAZIONE VISTA corsostudiodotmasview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[corsostudiodotmasview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[corsostudiodotmasview]
GO



CREATE VIEW [dbo].[corsostudiodotmasview] AS SELECT CASE WHEN corsostudio.almalaureasurvey = 'S' THEN 'Si' WHEN corsostudio.almalaureasurvey = 'N' THEN 'No' END AS corsostudio_almalaureasurvey, corsostudio.annoistituz AS corsostudio_annoistituz, corsostudio.basevoto AS corsostudio_basevoto, corsostudio.codice AS corsostudio_codice, corsostudio.codicemiur AS corsostudio_codicemiur, corsostudio.codicemiurlungo AS corsostudio_codicemiurlungo, corsostudio.crediti AS corsostudio_crediti, corsostudio.ct AS corsostudio_ct, corsostudio.cu AS corsostudio_cu, corsostudio.durata AS corsostudio_durata, corsostudio.idcorsostudio, corsostudio.idcorsostudiokind AS corsostudio_idcorsostudiokind, corsostudio.idcorsostudiolivello AS corsostudio_idcorsostudiolivello, corsostudio.idcorsostudionorma AS corsostudio_idcorsostudionorma, corsostudio.idduratakind AS corsostudio_idduratakind, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, corsostudio.idstruttura, corsostudio.lt AS corsostudio_lt, corsostudio.lu AS corsostudio_lu, corsostudio.obbform AS corsostudio_obbform, corsostudio.sboccocc AS corsostudio_sboccocc, corsostudio.title, corsostudio.title_en AS corsostudio_title_en,(select top 1 aa 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_aa,
						(select top 1 iddidprogsuddannokind 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_iddidprogsuddannokind,
						(select top 1 idgraduatoria 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as idgraduatoria,
						(select top 1 idnation_lang 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as idnation_lang,
						(select top 1 idnation_langvis 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as idnation_langvis,
						(select top 1 idsede 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as idsede,
						(select top 1 CASE WHEN didprog.immatoltreauth = 'S' THEN 'Si' WHEN didprog.immatoltreauth = 'N' THEN 'No' END AS didprog_immatoltreauth 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_immatoltreauth,
						(select top 1 startiscrizioni 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_startiscrizioni,
						(select top 1 stopiscrizioni 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_stopiscrizioni,
						(select top 1 title 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_title,
						(select top 1 title_en 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_title_en,
						(select top 1 utenzasost 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_utenzasost,
						(select top 1 website 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_website, isnull('Denominazione: ' + corsostudio.title + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') as dropdown_title FROM [dbo].corsostudio WITH (NOLOCK)  LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON corsostudio.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  corsostudio.idcorsostudio IS NOT NULL  AND corsostudio.idcorsostudiokind = 2

GO

-- CREAZIONE VISTA corsostudiostatoview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[corsostudiostatoview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[corsostudiostatoview]
GO



CREATE VIEW [dbo].[corsostudiostatoview] AS SELECT CASE WHEN corsostudio.almalaureasurvey = 'S' THEN 'Si' WHEN corsostudio.almalaureasurvey = 'N' THEN 'No' END AS corsostudio_almalaureasurvey, corsostudio.annoistituz AS corsostudio_annoistituz, corsostudio.basevoto AS corsostudio_basevoto, corsostudio.codice AS corsostudio_codice, corsostudio.codicemiur AS corsostudio_codicemiur, corsostudio.codicemiurlungo AS corsostudio_codicemiurlungo, corsostudio.crediti AS corsostudio_crediti, corsostudio.ct AS corsostudio_ct, corsostudio.cu AS corsostudio_cu, corsostudio.durata AS corsostudio_durata, corsostudio.idcorsostudio, corsostudio.idcorsostudiokind AS corsostudio_idcorsostudiokind, corsostudio.idcorsostudiolivello AS corsostudio_idcorsostudiolivello, corsostudio.idcorsostudionorma AS corsostudio_idcorsostudionorma, corsostudio.idduratakind AS corsostudio_idduratakind, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, corsostudio.idstruttura, corsostudio.lt AS corsostudio_lt, corsostudio.lu AS corsostudio_lu, corsostudio.obbform AS corsostudio_obbform, corsostudio.sboccocc AS corsostudio_sboccocc, corsostudio.title, corsostudio.title_en AS corsostudio_title_en,(select top 1 aa 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_aa,
						(select top 1 iddidprogsuddannokind 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_iddidprogsuddannokind,
						(select top 1 idsede 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as idsede,
						(select top 1 idsessione 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as idsessione,
						(select top 1 CASE WHEN didprog.immatoltreauth = 'S' THEN 'Si' WHEN didprog.immatoltreauth = 'N' THEN 'No' END AS didprog_immatoltreauth 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_immatoltreauth,
						(select top 1 startiscrizioni 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_startiscrizioni,
						(select top 1 stopiscrizioni 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_stopiscrizioni,
						(select top 1 title 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_title,
						(select top 1 title_en 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_title_en,
						(select top 1 utenzasost 
						from dbo.didprog 
						where dbo.didprog.idcorsostudio = corsostudio.idcorsostudio
						 order by didprog.title asc ) as didprog_utenzasost, isnull('Denominazione: ' + corsostudio.title + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') as dropdown_title FROM [dbo].corsostudio WITH (NOLOCK)  LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON corsostudio.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  corsostudio.idcorsostudio IS NOT NULL  AND corsostudio.idcorsostudiokind = 13

GO

